export class VolcVoice{
 constructor({api,status,message,onJobs,context}){Object.assign(this,{api,status,message,onJobs,context});this.generation=0;this.sources=new Set();this.playAt=0;this.audioGeneration=0;this.chain=Promise.resolve();}
 async connect(){if(this.connecting||this.ready)return;this.connecting=true;const gen=++this.generation;this.status('火山语音正在连接…');try{const conf=await this.api('/api/volc/status');if(!conf.configured)throw Error('火山语音未配置');this.audio=new AudioContext();await this.audio.resume();const stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;await this.audio.audioWorklet.addModule('/volc-capture.js');if(gen!==this.generation)return;this.capture=new AudioWorkletNode(this.audio,'volc-capture');this.source=this.audio.createMediaStreamSource(stream);const silence=this.audio.createGain();silence.gain.value=0;this.source.connect(this.capture);this.capture.connect(silence).connect(this.audio.destination);const token=await this.api('/api/volc/session',{contextSymbol:this.context?.()||''});if(gen!==this.generation)return;const ws=this.ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/volc`);ws.onopen=()=>ws.send(JSON.stringify({type:'init',token:token.token}));this.capture.port.onmessage=e=>{if(gen===this.generation&&this.ready&&ws.readyState===1){if(ws.bufferedAmount>262144){this.stop();this.status('语音上行拥堵，请重新接通');return}ws.send(e.data)}};ws.onmessage=e=>{if(gen!==this.generation)return;try{this.event(JSON.parse(e.data),gen)}catch{this.stop();this.status('语音事件解析失败')}};ws.onerror=()=>{if(gen===this.generation){this.stop();this.status('语音连接失败')}};ws.onclose=()=>{if(gen===this.generation){this.stop();this.status('语音已结束 · 后台研究继续')}};this.timeout=setTimeout(()=>{if(gen===this.generation&&!this.ready){this.stop();this.status('语音启动超时')}},22000)}catch(e){if(gen===this.generation){this.stop();this.status(e.message)}}}
 event(e,gen){if(e.type==='ready'){clearTimeout(this.timeout);this.ready=true;this.connecting=false;this.status('火山全双工已连接 · 请说话');return}if(e.type==='interrupt'){this.clearAudio();this.status('正在聆听…');return}if(e.type==='partial'){this.status('正在听：'+e.text.slice(-70));return}if(e.type==='user'){this.message('user',e.text);return}if(e.type==='working'){this.status('DeepSeek正在查询 · 可以继续说话');return}if(e.type==='result'){this.message('assistant',e.text);this.onJobs?.(e.jobs||[]);return}if(e.type==='job_complete'){this.message('assistant',e.text);this.onJobs?.([{id:e.id}]);return}if(e.type==='audio'){const ag=this.audioGeneration;this.chain=this.chain.then(async()=>{if(gen!==this.generation||ag!==this.audioGeneration)return;const raw=Uint8Array.from(atob(e.data),c=>c.charCodeAt(0));const buffer=await this.audio.decodeAudioData(raw.buffer);if(gen!==this.generation||ag!==this.audioGeneration)return;const s=this.audio.createBufferSource();s.buffer=buffer;s.connect(this.audio.destination);this.sources.add(s);s.onended=()=>{this.sources.delete(s);if(gen===this.generation&&ag===this.audioGeneration&&!this.sources.size&&this.ready)this.status('正在聆听…')};this.playAt=Math.max(this.audio.currentTime+.02,this.playAt);s.start(this.playAt);this.playAt+=buffer.duration;this.status('正在回答 · 可直接打断')}).catch(()=>this.status('音频播放失败，文字回答仍可查看'));return}if(e.type==='error'){this.stop();this.status(e.message)}}
 clearAudio(){this.audioGeneration++;for(const s of this.sources){try{s.stop()}catch{}}this.sources.clear();this.playAt=0;this.chain=Promise.resolve();}
 interrupt(){this.clearAudio();if(this.ws?.readyState===1)this.ws.send(JSON.stringify({type:'interrupt'}));}
 mute(value){this.stream?.getAudioTracks().forEach(t=>t.enabled=!value)}
 stop(){this.generation++;clearTimeout(this.timeout);this.ready=false;this.connecting=false;this.clearAudio();this.capture?.disconnect();this.source?.disconnect();this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;if(this.ws?.readyState===1)this.ws.send(JSON.stringify({type:'finish'}));this.ws?.close();this.ws=null;this.audio?.close().catch(()=>{});this.audio=null;}
}
